/* Токены — эталонная валидированная палитра (см. dataviz skill, palette.md).
   Цвета серий проверены валидатором: светлая и тёмная пары проходят все шесть
   проверок (CVD ΔE ≥ 8, нормальное зрение ≥ 15, контраст ≥ 3:1). */

.viz-widget {
  color-scheme: light;
  --surface-1: #fcfcfb;
  --text-primary: #0b0b0b;
  --text-secondary: #52514e;
  --text-muted: #898781;
  --gridline: #e1e0d9;
  --baseline: #c3c2b7;
  --series-1: #2a78d6;
  --series-2: #eb6834;
  --border-hairline: rgba(11, 11, 11, 0.1);
}

@media (prefers-color-scheme: dark) {
  body:not(.g-root_theme_light) .viz-widget {
    color-scheme: dark;
    --surface-1: #1a1a19;
    --text-primary: #f0efec;
    --text-secondary: #c3c2b7;
    --text-muted: #898781;
    --gridline: #2c2c2a;
    --baseline: #383835;
    --series-1: #3987e5;
    --series-2: #d95926;
    --border-hairline: rgba(255, 255, 255, 0.1);
  }
}

/* явный переключатель темы Gravity UI побеждает медиа-запрос */
body.g-root_theme_dark .viz-widget {
  color-scheme: dark;
  --surface-1: #1a1a19;
  --text-primary: #f0efec;
  --text-secondary: #c3c2b7;
  --text-muted: #898781;
  --gridline: #2c2c2a;
  --baseline: #383835;
  --series-1: #3987e5;
  --series-2: #d95926;
  --border-hairline: rgba(255, 255, 255, 0.1);
}

/* ── каркас виджета ── */

.viz-widget {
  display: block;
  padding: 16px 20px 12px;
  background: var(--surface-1);
  max-width: 860px;
}

.viz-widget__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 8px;
}

.viz-widget__heading {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.viz-widget__loading {
  padding: 4px 0;
}

/* ── легенда ── */

.viz-legend {
  display: flex;
  gap: 16px;
  margin: 2px 0 6px;
}

.viz-legend__item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.viz-legend__name {
  font: 13px/1.2 system-ui, -apple-system, 'Segoe UI', sans-serif;
  color: var(--text-secondary);
}

.viz-swatch {
  display: inline-block;
  width: 10px;
  height: 10px;
  border-radius: 2px;
  flex: none;
}

/* ── область графика ── */

.viz-engine {
  position: relative;
  width: 100%;
}

.viz-engine__svg {
  display: block;
  overflow: visible;
}

.viz-gridline {
  stroke: var(--gridline);
  stroke-width: 1;
}

.viz-baseline {
  stroke: var(--baseline);
  stroke-width: 1;
}

.viz-crosshair {
  stroke: var(--baseline);
  stroke-width: 1;
  stroke-dasharray: 3 3;
}

.viz-tick {
  font: 11px system-ui, -apple-system, 'Segoe UI', sans-serif;
  font-variant-numeric: tabular-nums;
  fill: var(--text-muted);
}

.viz-direct-label {
  font: 600 12px system-ui, -apple-system, 'Segoe UI', sans-serif;
  font-variant-numeric: tabular-nums;
  fill: var(--text-primary);
}

/* ── тултип ── */

.viz-tooltip {
  position: absolute;
  transform: translate(-50%, calc(-100% - 10px));
  pointer-events: none;
  background: var(--surface-1);
  border: 1px solid var(--border-hairline);
  border-radius: 8px;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.14);
  padding: 8px 10px;
  min-width: 120px;
  z-index: 2;
}

.viz-tooltip__title {
  font: 600 12px/1.3 system-ui, -apple-system, 'Segoe UI', sans-serif;
  color: var(--text-primary);
  margin-bottom: 4px;
  font-variant-numeric: tabular-nums;
}

.viz-tooltip__row {
  display: flex;
  align-items: center;
  gap: 6px;
  font: 12px/1.5 system-ui, -apple-system, 'Segoe UI', sans-serif;
}

.viz-tooltip__name {
  color: var(--text-secondary);
  flex: 1;
}

.viz-tooltip__value {
  color: var(--text-primary);
  font-variant-numeric: tabular-nums;
  font-weight: 600;
}

/* ── табличное представление ── */

.viz-table-details {
  margin-top: 10px;
  border-top: 1px solid var(--gridline);
  padding-top: 8px;
}

.viz-table-details summary {
  cursor: pointer;
  list-style: none;
}

.viz-table-details summary::-webkit-details-marker {
  display: none;
}

.viz-table-details summary:hover {
  text-decoration: underline;
}

.viz-table-wrap {
  max-height: 260px;
  overflow: auto;
  margin-top: 8px;
}

.viz-table {
  border-collapse: collapse;
  width: 100%;
  font: 12px/1.6 system-ui, -apple-system, 'Segoe UI', sans-serif;
  color: var(--text-primary);
}

.viz-table th {
  position: sticky;
  top: 0;
  background: var(--surface-1);
  text-align: left;
  font-weight: 600;
  color: var(--text-secondary);
  border-bottom: 1px solid var(--baseline);
  padding: 4px 12px 4px 0;
  white-space: nowrap;
}

.viz-table td {
  border-bottom: 1px solid var(--gridline);
  padding: 3px 12px 3px 0;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.viz-table__num {
  text-align: right;
}

