import {chromium} from 'playwright-core';

const URL = 'http://localhost:4199/';
const browser = await chromium.launch();
const page = await browser.newPage({viewport: {width: 960, height: 760}});

await page.goto(URL, {waitUntil: 'networkidle'});
await page.waitForSelector('.viz-engine svg', {timeout: 10000});
await page.waitForTimeout(300);
await page.screenshot({path: '/tmp/shot/01-sales-light.png'});

// hover по графику продаж — проверить кроссхеер и тултип
const box = await page.locator('.viz-engine').boundingBox();
await page.mouse.move(box.x + box.width * 0.7, box.y + box.height * 0.5);
await page.waitForTimeout(200);
await page.screenshot({path: '/tmp/shot/02-sales-hover.png'});

// переключиться на мониторинг (ленивый чанк)
await page.getByRole('radio', {name: 'Мониторинг'}).click();
await page.waitForSelector('.viz-engine canvas', {timeout: 10000});
await page.waitForTimeout(300);
await page.screenshot({path: '/tmp/shot/03-monitoring-light.png'});

// hover по мониторингу
await page.mouse.move(box.x + box.width * 0.58, box.y + box.height * 0.5);
await page.waitForTimeout(200);
await page.screenshot({path: '/tmp/shot/04-monitoring-hover.png'});

// тёмная тема
await page.getByRole('switch').click();
await page.waitForTimeout(300);
await page.screenshot({path: '/tmp/shot/05-monitoring-dark.png'});

// назад к продажам в тёмной теме
await page.getByRole('radio', {name: 'Продажи'}).click();
await page.waitForSelector('.viz-engine svg', {timeout: 10000});
await page.waitForTimeout(300);
await page.screenshot({path: '/tmp/shot/06-sales-dark.png'});

// таблица
await page.locator('.viz-table-details summary').click();
await page.waitForTimeout(200);
await page.screenshot({path: '/tmp/shot/07-table.png'});

await browser.close();
console.log('screenshots done');

