import {chromium} from 'playwright-core';

const browser = await chromium.launch({
  args: ['--no-sandbox', '--disable-gpu', '--no-zygote', '--single-process', '--enable-unsafe-swiftshader'],
});
const page = await browser.newPage({viewport: {width: 960, height: 760}});
await page.goto('http://localhost:4199/', {waitUntil: 'networkidle'});
await page.waitForSelector('.viz-engine svg');
const info = await page.evaluate(() => {
  const s = document.querySelector('.viz-table-details summary');
  const d = document.querySelector('.viz-table-details');
  const r = s.getBoundingClientRect();
  const cs = getComputedStyle(s);
  return {
    rect: {w: r.width, h: r.height, x: r.x, y: r.y},
    display: cs.display,
    visibility: cs.visibility,
    detailsHTML: d.outerHTML.slice(0, 400),
  };
});
console.log(JSON.stringify(info, null, 2));
await browser.close();

