import {chromium} from 'playwright-core';

const browser = await chromium.launch({
  args: ['--no-sandbox', '--disable-gpu', '--no-zygote', '--single-process', '--enable-unsafe-swiftshader'],
});
const page = await browser.newPage({viewport: {width: 960, height: 760}});
await page.goto('http://localhost:4199/', {waitUntil: 'networkidle'});
await page.waitForSelector('.viz-engine svg');

const isOpen = () => page.evaluate(() => document.querySelector('.viz-table-details').open);
console.log('initial:', await isOpen());
await page.getByRole('radio', {name: 'Мониторинг'}).click();
await page.waitForSelector('.viz-engine canvas');
console.log('after ->monitoring:', await isOpen());
await page.getByRole('radio', {name: 'Продажи'}).click();
await page.waitForSelector('.viz-engine svg');
console.log('after ->sales:', await isOpen());
await page.locator('.viz-table-details summary').click();
console.log('after summary click:', await isOpen());
await browser.close();

