args.content:
import {chromium} from 'playwright-core';

const browser = await chromium.launch({
  args: ['--no-sandbox', '--disable-gpu', '--no-zygote', '--single-process', '--enable-unsafe-swiftshader'],
});
const page = await browser.newPage();
const jsRequests = [];
page.on('request', (r) => {
  if (r.url().includes('/assets/') && r.url().endsWith('.js')) jsRequests.push(r.url().split('/').pop());
});

await page.goto('http://localhost:4199/', {waitUntil: 'networkidle'});
await page.waitForSelector('.viz-engine svg');
console.log('JS loaded on initial render (sales):', jsRequests.join(', '));
console.log('MonitoringChart loaded?', jsRequests.some((f) => f.includes('Monitoring')));

await page.getByRole('radio', {name: 'Мониторинг'}).click();
await page.waitForSelector('.viz-engine canvas');
await page.waitForTimeout(300);
console.log('after switching:', jsRequests.join(', '));
await browser.close();

